Middleware Architecture & Error Handling:
// Express error handling patterns
import express from 'express';
import 'express-async-errors';

const app = express();

// Custom error class
class AppError extends Error {
  constructor(public statusCode: number, message: string) {
    super(message);
    this.name = 'AppError';
  }
}

// Async wrapper (alternative to express-async-errors)
function asyncHandler(fn: Function) {
  return (req: Request, res: Response, next: NextFunction) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

// Routes with error handling
app.get('/api/users/:id', asyncHandler(async (req, res) => {
  const user = await db.users.findById(req.params.id);
  if (!user) throw new AppError(404, 'User not found');
  res.json(user);
}));

// Centralized error handler (4 params)
app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
  // Log error
  logger.error({
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method
  });

  // Determine status code
  const statusCode = err instanceof AppError ? err.statusCode : 500;

  // Send safe response
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production' && statusCode === 500
      ? 'Internal server error'
      : err.message,
    code: statusCode >= 500 ? 'INTERNAL_ERROR' : 'VALIDATION_ERROR'
  });
});

Express WebSocket & Real-Time:
// Express + Socket.IO setup
import express from 'express';
import { createServer } from 'http';
import { Server } from 'socket.io';
import { createAdapter } from '@socket.io/redis-adapter';
import { createClient } from 'redis';

const app = express();
const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: { origin: process.env.CLIENT_URL, methods: ['GET', 'POST'] },
  // Production: use Redis adapter for horizontal scaling
});

// Redis adapter for multi-instance
const pubClient = createClient({ url: process.env.REDIS_URL });
const subClient = pubClient.duplicate();
io.adapter(createAdapter(pubClient, subClient));

// Authentication middleware
io.use(async (socket, next) => {
  const token = socket.handshake.auth.token;
  try {
    const user = await verifyToken(token);
    socket.data.user = user;
    next();
  } catch (err) {
    next(new Error('Authentication failed'));
  }
});

io.on('connection', (socket) => {
  const userId = socket.data.user.id;
  console.log(`User ${userId} connected`);

  // Join user-specific room
  socket.join(`user:${userId}`);

  socket.on('send-message', async ({ to, content }, ack) => {
    const message = await db.messages.create({
      from: userId,
      to,
      content
    });
    // Emit to recipient's room
    io.to(`user:${to}`).emit('new-message', message);
    // Acknowledge
    ack({ status: 'sent', id: message.id });
  });

  socket.on('typing', ({ to }) => {
    socket.to(`user:${to}`).emit('user-typing', { userId });
  });

  // REST endpoint that emits socket event
  app.post('/api/notifications', (req, res) => {
    const { userId, notification } = req.body;
    io.to(`user:${userId}`).emit('notification', notification);
    res.json({ sent: true });
  });

  socket.on('disconnect', () => {
    console.log(`User ${userId} disconnected`);
  });
});

httpServer.listen(3000, () => console.log('Server on :3000'));
